UPDATE medication_plan
SET next_remind_at = #{nextRemindAt},
    updated_at = #{now}
WHERE id = #{planId}
  AND next_remind_at = #{dueAt}
  AND status = 'ACTIVE'
  AND reminder_enabled = true
  AND deleted_at IS NULL

