SELECT 
FROM notification n
WHERE n.user_id = #{userId}
  AND n.deleted_at IS NULL
  AND n.patient_id = #{patientId}
  AND n.type = #{type}

      AND n.read_at IS NOT NULLn.read_at IS NULL

ORDER BY n.created_at DESC, n.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM notification n
WHERE n.user_id = #{userId}
